'use client';
// TDM-97: 3D digital twin of the I2RT YAM, driven by RobotLiveState (E15 robot view contract,
// docs/WORKER_GUIDE.md). Purely presentational: no data fetching. Lazy-load it with
// next/dynamic + ssr:false (RobotView does).
//
// Model: the SDK's own YAM v1 + linear_4310 (i2rt-robotics/i2rt@120c3c8, MIT), the same model
// yam_kinematics.py and the MuJoCo sim use: kinematic tree in ./yamModel.ts, decimated meshes in
// /robot/yam/yam.glb (both generated by spikes/tdm-97/build_yam_assets.py). The FK spot check is
// apps/web/test/robotview-twin-fk.test.ts.
//
// Frames: everything robot-side is placed in the robot base frame (x forward, y left, z up, m)
// inside one group that maps it onto three.js's y-up world: robot (x, y, z) -> three (x, z, -y).
import { CameraControls, Environment, Grid, Lightformer, Line, PerformanceMonitor, RoundedBox, useGLTF } from '@react-three/drei';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { Suspense, useEffect, useMemo, useRef, useState, type MutableRefObject } from 'react';
import * as THREE from 'three';
import { toCreasedNormals } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import type { RobotLiveState, Vec3 } from '@/lib/robotview/types';
import { createYamKinematics, YAM_REST, type Mat4 } from './yamFk';
import { YAM_BODIES, YAM_GRASP_SITE, YAM_MODEL, YAM_WRIST_CAMERA, type YamBody } from './yamModel';

export type TwinPreset = 'front' | 'top' | 'wrist';

export interface RobotTwin3DProps {
  state: RobotLiveState | null;
  preset?: TwinPreset;
  /** The sim robot: draws the scene's engineering grid on the table (RobotView owns the SIMULATED label). */
  sim?: boolean;
  /** Joint-space targets (rad, >= 6 per row) to draw as a ghost: tool-point path + the arm at the last row. */
  ghost?: number[][];
  className?: string;
}

const GLB_URL = '/robot/yam/yam.glb';
const KIN = createYamKinematics(YAM_MODEL);

// ---------------------------------------------------------------------------------------- palette
// Dusk studio: a cool slate cyclorama the arm sits in, a warm stone bench, graphite + bead-blasted
// aluminium links. Colour carries meaning only where it matters: amber = the safety envelope,
// ice blue = what the policy intends next, red = e-stop. Cube and plate keep the MuJoCo scene's
// colours so the twin and the sim camera read as the same scene.
const C = {
  stage: '#2b323c',
  stageSim: '#2f2c40', // the sim frame is violet (RobotView); the stage leans that way too
  floor: '#232931',
  bench: '#bdb6a9',
  benchEdge: '#9f9788',
  graphite: '#2a2e35',
  aluminium: '#b6bbc2',
  sensor: '#17191d',
  envelope: '#f0a63a',
  intent: '#8cc2ff',
  estop: '#ff4d4f',
  cube: '#db1f1a',
  plate: '#f0f0eb',
  plateRim: '#3366cc',
};

/** Which links are anodised graphite and which are bare aluminium (alternating reads as machined). */
const FINISH: Record<string, 'graphite' | 'aluminium' | 'sensor'> = {
  base: 'graphite',
  link1: 'aluminium',
  link2: 'graphite',
  link3: 'graphite',
  link4: 'aluminium',
  link5: 'graphite',
  gripper: 'graphite',
  tip_left: 'aluminium',
  tip_right: 'aluminium',
  wrist_cam_mount: 'sensor',
};

// ---------------------------------------------------------------------------------------- cameras
// `front` is the MuJoCo sim's exo camera (mujoco_scene.SceneSpec.top_pos/top_target, fovy 52), so
// the twin lines up with the sim camera pane. `top` looks straight down with the arm reaching up.
const PRESETS: Record<Exclude<TwinPreset, 'wrist'>, { pos: Vec3; target: Vec3; fov: number }> = {
  front: { pos: [0.86, -0.5, 0.58], target: [0.27, 0.03, 0.06], fov: 52 },
  top: { pos: [0.299, 0, 1.32], target: [0.3, 0, 0], fov: 45 },
};

const r2t = (v: readonly number[]): [number, number, number] => [v[0], v[2], -v[1]];
const ROBOT_TO_THREE = new THREE.Matrix4().makeRotationX(-Math.PI / 2);
const quatWxyz = (q: readonly number[]) => new THREE.Quaternion(q[1], q[2], q[3], q[0]);

// ---------------------------------------------------------------------------------------- smoothing
// State arrives at 10-30 Hz; the arm is drawn every frame by easing towards the latest sample
// (critically damped first-order, ~60 ms time constant), so motion is continuous without lagging.
const EASE_PER_S = 16;

interface Smoothed {
  init: boolean;
  q: number[];
  gripper: number;
  cube: THREE.Vector3;
  cubeQ: THREE.Quaternion;
  plate: THREE.Vector3;
  ghostQ: number[] | null;
}

function newSmoothed(): Smoothed {
  return { init: false, q: [...YAM_REST], gripper: 1, cube: new THREE.Vector3(), cubeQ: new THREE.Quaternion(), plate: new THREE.Vector3(), ghostQ: null };
}

function Driver({ stateRef, ghostRef, smooth }: { stateRef: MutableRefObject<RobotLiveState | null>; ghostRef: MutableRefObject<number[] | null>; smooth: Smoothed }) {
  const tmpV = useMemo(() => new THREE.Vector3(), []);
  const tmpQ = useMemo(() => new THREE.Quaternion(), []);
  useFrame((_, dt) => {
    const s = stateRef.current;
    const a = smooth.init ? 1 - Math.exp(-EASE_PER_S * Math.min(dt, 0.1)) : 1;
    if (s) {
      for (let i = 0; i < 6; i++) {
        const t = s.joints[i];
        if (Number.isFinite(t)) smooth.q[i] += (t - smooth.q[i]) * a;
      }
      if (Number.isFinite(s.gripper)) smooth.gripper += (s.gripper - smooth.gripper) * a;
      const cube = s.scene?.cube;
      if (cube) {
        smooth.cube.lerp(tmpV.set(cube.pos[0], cube.pos[1], cube.pos[2]), a);
        smooth.cubeQ.slerp(tmpQ.set(cube.quat[1], cube.quat[2], cube.quat[3], cube.quat[0]).normalize(), a);
      }
      const plate = s.scene?.plate;
      if (plate) smooth.plate.lerp(tmpV.set(plate.pos[0], plate.pos[1], plate.pos[2]), a);
      smooth.init = true;
    }
    const g = ghostRef.current;
    if (g) {
      if (!smooth.ghostQ) smooth.ghostQ = [...g];
      else for (let i = 0; i < 6; i++) smooth.ghostQ[i] += (g[i] - smooth.ghostQ[i]) * a;
    } else smooth.ghostQ = null;
  }, -1);
  return null;
}

// ---------------------------------------------------------------------------------------- the arm
type Geoms = Record<string, THREE.BufferGeometry[]>; // body name -> its mesh geometries

const GEOM_CACHE = new WeakMap<object, Geoms>(); // shared by the arm and its ghost

function useArmGeometries(): Geoms {
  const gltf = useGLTF(GLB_URL);
  return useMemo(() => {
    const hit = GEOM_CACHE.get(gltf.scene);
    if (hit) return hit;
    const out: Geoms = {};
    gltf.scene.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      const body = m.name.split('__')[0];
      // CAD meshes: crease at 35 deg so flats stay flat and fillets stay round.
      const g = toCreasedNormals(m.geometry, (35 * Math.PI) / 180);
      (out[body] ??= []).push(g);
    });
    GEOM_CACHE.set(gltf.scene, out);
    return out;
  }, [gltf]);
}

// The ghost draws only the hand (where the policy is taking it): a whole translucent arm on top of
// the real one reads as a smear.
const GHOST_BODIES: ReadonlySet<string> = new Set(['gripper', 'tip_left', 'tip_right', 'wrist_cam_mount']);

const CHILDREN: Record<string, YamBody[]> = {};
for (const b of YAM_BODIES) (CHILDREN[b.parent] ??= []).push(b);

function Body({ body, geoms, materials, jointRefs, graspRef, shadows, only }: {
  body: YamBody;
  only?: ReadonlySet<string>;
  geoms: Geoms;
  materials: Record<string, THREE.Material>;
  jointRefs: MutableRefObject<Record<string, THREE.Group | null>>;
  graspRef?: MutableRefObject<THREE.Object3D | null>;
  shadows: boolean;
}) {
  const quat = useMemo(() => quatWxyz(body.quat), [body.quat]);
  return (
    <group position={body.pos as unknown as [number, number, number]} quaternion={quat}>
      <group ref={(g) => { if (body.joint) jointRefs.current[body.joint.name] = g; }}>
        {(!only || only.has(body.name) ? (geoms[body.name] ?? []) : []).map((g, i) => (
          <mesh key={i} geometry={g} material={materials[FINISH[body.name] ?? 'graphite']} castShadow={shadows} />
        ))}
        {graspRef && body.name === YAM_GRASP_SITE.body && (
          <object3D ref={graspRef} position={YAM_GRASP_SITE.pos as unknown as [number, number, number]} quaternion={quatWxyz(YAM_GRASP_SITE.quat)} />
        )}
        {(CHILDREN[body.name] ?? []).map((c) => (
          <Body key={c.name} body={c} geoms={geoms} materials={materials} jointRefs={jointRefs} graspRef={graspRef} shadows={shadows} only={only} />
        ))}
      </group>
    </group>
  );
}

function Arm({ read, materials, graspRef, shadows = true, only }: {
  /** Draw only these bodies' meshes (the chain is still posed in full). */
  only?: ReadonlySet<string>;
  read: () => { q: number[]; gripper: number } | null;
  materials: Record<string, THREE.Material>;
  graspRef?: MutableRefObject<THREE.Object3D | null>;
  shadows?: boolean;
}) {
  const geoms = useArmGeometries();
  const jointRefs = useRef<Record<string, THREE.Group | null>>({});
  const root = useRef<THREE.Group>(null);
  const axes = useMemo(() => {
    const m: Record<string, { type: 'hinge' | 'slide'; axis: THREE.Vector3 }> = {};
    for (const b of YAM_BODIES) if (b.joint) m[b.joint.name] = { type: b.joint.type, axis: new THREE.Vector3(...b.joint.axis).normalize() };
    return m;
  }, []);
  useFrame(() => {
    const r = read();
    if (root.current) root.current.visible = !!r;
    if (!r) return;
    const vals = KIN.jointValues(r.q, r.gripper);
    for (const [name, j] of Object.entries(axes)) {
      const g = jointRefs.current[name];
      if (!g) continue;
      const v = vals[name] ?? 0;
      if (j.type === 'hinge') g.quaternion.setFromAxisAngle(j.axis, v);
      else g.position.copy(j.axis).multiplyScalar(v);
    }
  });
  return (
    <group ref={root}>
      {(CHILDREN.world ?? []).map((b) => (
        <Body key={b.name} body={b} geoms={geoms} materials={materials} jointRefs={jointRefs} graspRef={graspRef} shadows={shadows} only={only} />
      ))}
    </group>
  );
}

function useArmMaterials() {
  return useMemo(() => {
    const solid = {
      graphite: new THREE.MeshPhysicalMaterial({ color: C.graphite, metalness: 0.35, roughness: 0.38, clearcoat: 0.6, clearcoatRoughness: 0.28, envMapIntensity: 1.4 }),
      aluminium: new THREE.MeshPhysicalMaterial({ color: C.aluminium, metalness: 0.75, roughness: 0.3, envMapIntensity: 1.6 }),
      sensor: new THREE.MeshPhysicalMaterial({ color: C.sensor, metalness: 0.2, roughness: 0.25, clearcoat: 0.8 }),
    };
    const ghostMat = new THREE.MeshStandardMaterial({
      color: C.intent, emissive: C.intent, emissiveIntensity: 0.6, transparent: true, opacity: 0.28, depthWrite: true, roughness: 0.6,
    });
    const ghost = { graphite: ghostMat, aluminium: ghostMat, sensor: ghostMat };
    return { solid, ghost };
  }, []);
}

// ---------------------------------------------------------------------------------------- scene
function Bench({ tableZ, sim }: { tableZ: number; sim: boolean }) {
  // The MuJoCo scene's table: 0.96 m square top centred at x = 0.30, top surface at z = 0.
  const top = r2t([0.3, 0, tableZ - 0.02]);
  return (
    <group>
      <RoundedBox args={[0.96, 0.04, 0.96]} radius={0.008} smoothness={3} position={top} receiveShadow>
        <meshStandardMaterial color={C.bench} roughness={0.88} metalness={0} />
      </RoundedBox>
      {[[-0.14, -0.44], [-0.14, 0.44], [0.74, -0.44], [0.74, 0.44]].map(([x, y], i) => (
        <mesh key={i} position={r2t([x, y, tableZ - 0.39])}>
          <boxGeometry args={[0.05, 0.7, 0.05]} />
          <meshStandardMaterial color={C.graphite} roughness={0.6} metalness={0.4} />
        </mesh>
      ))}
      {sim && (
        <Grid
          position={r2t([0.3, 0, tableZ + 0.0006])}
          args={[0.96, 0.96]}
          cellSize={0.05}
          cellThickness={0.5}
          cellColor={C.benchEdge}
          sectionSize={0.25}
          sectionThickness={1}
          sectionColor="#a39bc4"
          fadeDistance={6}
          followCamera={false}
        />
      )}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, tableZ - 0.74, 0]} receiveShadow>
        <planeGeometry args={[12, 12]} />
        <meshStandardMaterial color={C.floor} roughness={1} />
      </mesh>
    </group>
  );
}

function Envelope({ ws, estop }: { ws: NonNullable<RobotLiveState['workspace']>; estop: boolean }) {
  const size: Vec3 = [ws.max[0] - ws.min[0], ws.max[1] - ws.min[1], ws.max[2] - ws.min[2]];
  const centre: Vec3 = [(ws.max[0] + ws.min[0]) / 2, (ws.max[1] + ws.min[1]) / 2, (ws.max[2] + ws.min[2]) / 2];
  const edges = useMemo(() => new THREE.EdgesGeometry(new THREE.BoxGeometry(...size)), [size[0], size[1], size[2]]); // eslint-disable-line react-hooks/exhaustive-deps
  const color = estop ? C.estop : C.envelope;
  return (
    <group position={centre}>
      <lineSegments geometry={edges}>
        <lineBasicMaterial color={color} transparent opacity={estop ? 1 : 0.85} />
      </lineSegments>
      <mesh>
        <boxGeometry args={size} />
        <meshBasicMaterial color={color} transparent opacity={estop ? 0.07 : 0.028} depthWrite={false} side={THREE.DoubleSide} />
      </mesh>
      {/* footprint on the bench */}
      <mesh position={[0, 0, ws.table_z - centre[2] + 0.0012]}>
        <planeGeometry args={[size[0], size[1]]} />
        <meshBasicMaterial color={color} transparent opacity={estop ? 0.16 : 0.09} depthWrite={false} />
      </mesh>
    </group>
  );
}

function SceneObjects({ smooth, hasCube, hasPlate }: { smooth: Smoothed; hasCube: boolean; hasPlate: boolean }) {
  const cube = useRef<THREE.Mesh>(null);
  const plate = useRef<THREE.Group>(null);
  useFrame(() => {
    if (cube.current) {
      cube.current.position.copy(smooth.cube);
      cube.current.quaternion.copy(smooth.cubeQ);
    }
    if (plate.current) plate.current.position.copy(smooth.plate);
  });
  return (
    <>
      {hasCube && (
        <mesh ref={cube} castShadow>
          <boxGeometry args={[0.04, 0.04, 0.04]} />
          <meshStandardMaterial color={C.cube} roughness={0.5} />
        </mesh>
      )}
      {hasPlate && (
        <group ref={plate}>
          {/* the sim's plate: r 7.5 cm, 12 mm disc with a coloured rim (mujoco_scene.py) */}
          <mesh position={[0, 0, 0.006]} rotation={[Math.PI / 2, 0, 0]} receiveShadow castShadow>
            <cylinderGeometry args={[0.075, 0.075, 0.012, 48]} />
            <meshStandardMaterial color={C.plate} roughness={0.5} />
          </mesh>
          <mesh position={[0, 0, 0.016]}>
            <torusGeometry args={[0.075, 0.005, 10, 48]} />
            <meshStandardMaterial color={C.plateRim} roughness={0.4} />
          </mesh>
        </group>
      )}
    </>
  );
}

function GhostPath({ rows }: { rows: number[][] }) {
  const pts = useMemo(() => rows.filter((r) => r.length >= 6 && r.slice(0, 6).every(Number.isFinite)).map((r) => KIN.graspSitePos(r)), [rows]);
  if (pts.length < 2) return null;
  return (
    <group>
      <Line points={pts} color={C.intent} lineWidth={2.2} transparent opacity={0.9} />
      {pts.map((p, i) => (
        <mesh key={i} position={p}>
          <sphereGeometry args={[i === pts.length - 1 ? 0.007 : 0.0035, 12, 8]} />
          <meshBasicMaterial color={C.intent} transparent opacity={i === pts.length - 1 ? 0.95 : 0.6} />
        </mesh>
      ))}
    </group>
  );
}

function EstopRing({ on }: { on: boolean }) {
  const ref = useRef<THREE.Mesh>(null);
  useFrame(({ clock }) => {
    if (!ref.current) return;
    ref.current.visible = on;
    const m = ref.current.material as THREE.MeshBasicMaterial;
    m.opacity = 0.55 + 0.35 * Math.sin(clock.elapsedTime * 5);
  });
  return (
    <mesh ref={ref} position={[0, 0, 0.002]}>
      <ringGeometry args={[0.075, 0.09, 64]} />
      <meshBasicMaterial color={C.estop} transparent depthWrite={false} />
    </mesh>
  );
}

// ---------------------------------------------------------------------------------------- camera rigs
function OrbitRig({ preset, controlsRef, onUserMove }: {
  preset: Exclude<TwinPreset, 'wrist'>;
  controlsRef: MutableRefObject<CameraControls | null>;
  onUserMove: () => void;
}) {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  const first = useRef(true);
  useEffect(() => {
    const c = controlsRef.current;
    if (!c) return;
    const p = PRESETS[preset];
    camera.fov = p.fov;
    camera.updateProjectionMatrix();
    void c.setLookAt(...r2t(p.pos), ...r2t(p.target), !first.current);
    first.current = false;
  }, [preset, camera, controlsRef]);
  useEffect(() => {
    const c = controlsRef.current;
    if (!c) return;
    const h = () => onUserMove();
    c.addEventListener('controlstart', h);
    return () => c.removeEventListener('controlstart', h);
  }, [controlsRef, onUserMove]);
  return (
    <CameraControls
      ref={controlsRef}
      makeDefault
      minDistance={0.25}
      maxDistance={3.2}
      maxPolarAngle={Math.PI * 0.49}
      smoothTime={0.35}
      draggingSmoothTime={0.08}
    />
  );
}

/** Rides the D405 on the flange: the same pose and fov as the sim's `wrist` camera. */
function WristRig({ smooth }: { smooth: Smoothed }) {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  const m = useMemo(() => new THREE.Matrix4(), []);
  const site = useMemo(() => new THREE.Matrix4().compose(new THREE.Vector3(...YAM_WRIST_CAMERA.pos), quatWxyz(YAM_WRIST_CAMERA.quat), new THREE.Vector3(1, 1, 1)), []);
  useEffect(() => {
    camera.fov = YAM_WRIST_CAMERA.fovy;
    camera.updateProjectionMatrix();
  }, [camera]);
  useFrame(() => {
    const t: Mat4 = KIN.bodyTransforms(smooth.q, smooth.gripper)[YAM_WRIST_CAMERA.body];
    m.fromArray(Array.from(t)).multiply(site).premultiply(ROBOT_TO_THREE);
    m.decompose(camera.position, camera.quaternion, camera.scale);
    camera.updateMatrixWorld();
  });
  return null;
}

// ---------------------------------------------------------------------------------------- dev probe
declare global {
  interface Window {
    __rdfTwin?: { ee: () => Vec3 | null; q: () => number[]; fps: () => number };
  }
}

function DevProbe({ graspRef, smooth }: { graspRef: MutableRefObject<THREE.Object3D | null>; smooth: Smoothed }) {
  const frames = useRef<number[]>([]);
  useFrame(() => {
    const now = performance.now();
    const f = frames.current;
    f.push(now);
    while (f.length && now - f[0] > 1000) f.shift();
  });
  useEffect(() => {
    if (process.env.NODE_ENV === 'production') return;
    const v = new THREE.Vector3();
    window.__rdfTwin = {
      // world position of the grasp_site node in the rendered scene graph, back in the robot frame
      ee: () => {
        const o = graspRef.current;
        if (!o) return null;
        o.getWorldPosition(v);
        return [v.x, -v.z, v.y];
      },
      q: () => [...smooth.q],
      fps: () => frames.current.length,
    };
    return () => {
      delete window.__rdfTwin;
    };
  }, [graspRef, smooth]);
  return null;
}

// ---------------------------------------------------------------------------------------- component
export function RobotTwin3D({ state, preset = 'front', sim = false, ghost, className }: RobotTwin3DProps) {
  const stateRef = useRef<RobotLiveState | null>(state);
  stateRef.current = state;
  const ghostRows = ghost && ghost.length ? ghost : null;
  const ghostLast = ghostRows ? ghostRows[ghostRows.length - 1] : null;
  const ghostRef = useRef<number[] | null>(null);
  ghostRef.current = ghostLast && ghostLast.length >= 6 && ghostLast.slice(0, 6).every(Number.isFinite) ? ghostLast : null;

  const smooth = useMemo(newSmoothed, []);
  const graspRef = useRef<THREE.Object3D | null>(null);
  const controlsRef = useRef<CameraControls | null>(null);
  const [moved, setMoved] = useState(false);
  const [dpr, setDpr] = useState<number>(1.5);
  const [narrow, setNarrow] = useState(false);
  useEffect(() => {
    setDpr(Math.min(2, window.devicePixelRatio || 1));
    const mq = window.matchMedia('(max-width: 640px)');
    const on = () => setNarrow(mq.matches);
    on();
    mq.addEventListener('change', on);
    return () => mq.removeEventListener('change', on);
  }, []);
  useEffect(() => setMoved(false), [preset]);

  const ws = state?.workspace;
  const tableZ = ws?.table_z ?? 0;
  const estop = !!state?.estop;
  const hasCube = !!state?.scene?.cube;
  const hasPlate = !!state?.scene?.plate;
  const mats = useArmMaterials();

  const resetView = () => {
    const c = controlsRef.current;
    if (!c || preset === 'wrist') return;
    const p = PRESETS[preset];
    void c.setLookAt(...r2t(p.pos), ...r2t(p.target), true);
    setMoved(false);
  };

  return (
    <div
      className={`relative h-full w-full select-none ${className ?? ''}`}
      role="img"
      aria-label={`3D view of the YAM arm${state ? '' : ' (no joint state yet, shown at rest)'}${estop ? ', e-stop engaged' : ''}`}
      data-twin-ready={state ? 'live' : 'rest'}
    >
      <Canvas
        shadows="variance"
        dpr={dpr}
        gl={{ antialias: true, powerPreference: 'high-performance' }}
        camera={{ fov: PRESETS.front.fov, near: 0.01, far: 30, position: r2t(PRESETS.front.pos) }}
        style={{ touchAction: preset === 'wrist' ? 'auto' : 'none' }}
      >
        <PerformanceMonitor onDecline={() => setDpr(1)} onIncline={() => setDpr(Math.min(2, window.devicePixelRatio || 1))} />
        <color attach="background" args={[sim ? C.stageSim : C.stage]} />
        <fog attach="fog" args={[sim ? C.stageSim : C.stage, 2.4, 7.5]} />

        <hemisphereLight args={['#dfe7f2', '#2b2f36', 0.4]} />
        <directionalLight
          position={r2t([0.6, -0.6, 1.6])}
          intensity={2.8}
          castShadow
          shadow-mapSize={narrow ? [1024, 1024] : [2048, 2048]}
          shadow-camera-left={-0.8}
          shadow-camera-right={0.8}
          shadow-camera-top={0.8}
          shadow-camera-bottom={-0.8}
          shadow-camera-near={0.2}
          shadow-camera-far={4}
          shadow-radius={9}
          shadow-blurSamples={narrow ? 8 : 16}
          shadow-bias={-0.0006}
        />
        <directionalLight position={r2t([-0.5, 0.7, 0.9])} intensity={0.5} color="#c9d6ff" />

        <Environment resolution={128} frames={1}>
          <Lightformer form="rect" intensity={2.2} position={[0, 3, 0]} rotation={[Math.PI / 2, 0, 0]} scale={[4, 4, 1]} />
          <Lightformer form="rect" intensity={1.4} color="#ffe9cf" position={[3, 1.2, 1.5]} rotation={[0, -Math.PI / 2.4, 0]} scale={[2.5, 1, 1]} />
          <Lightformer form="rect" intensity={0.9} color="#cfe0ff" position={[-3, 1, -1]} rotation={[0, Math.PI / 2.2, 0]} scale={[3, 0.6, 1]} />
          <Lightformer form="ring" intensity={0.6} position={[0, 1, -4]} scale={2} />
        </Environment>

        <Driver stateRef={stateRef} ghostRef={ghostRef} smooth={smooth} />
        <Bench tableZ={tableZ} sim={sim} />

        {/* robot base frame (z up) */}
        <group rotation={[-Math.PI / 2, 0, 0]}>
          <Suspense fallback={null}>
            <Arm read={() => ({ q: smooth.q, gripper: smooth.gripper })} materials={mats.solid} graspRef={graspRef} />
            {ghostRows && <Arm read={() => (smooth.ghostQ ? { q: smooth.ghostQ, gripper: smooth.gripper } : null)} materials={mats.ghost} shadows={false} only={GHOST_BODIES} />}
          </Suspense>
          {ws && <Envelope ws={ws} estop={estop} />}
          <EstopRing on={estop} />
          <SceneObjects smooth={smooth} hasCube={hasCube} hasPlate={hasPlate} />
          {ghostRows && <GhostPath rows={ghostRows} />}
        </group>

        {preset === 'wrist' ? <WristRig smooth={smooth} /> : <OrbitRig preset={preset} controlsRef={controlsRef} onUserMove={() => setMoved(true)} />}
        <DevProbe graspRef={graspRef} smooth={smooth} />
      </Canvas>

      {moved && preset !== 'wrist' && (
        <button
          type="button"
          onClick={resetView}
          className="absolute right-2 top-11 rounded-md bg-black/45 px-2.5 py-1 text-xs font-medium text-white/90 backdrop-blur-sm hover:bg-black/60 focus-visible:outline focus-visible:outline-2 focus-visible:outline-white"
        >
          Reset view
        </button>
      )}
    </div>
  );
}

useGLTF.preload(GLB_URL);

export default RobotTwin3D;
